effect.script:
function animate(env,el,p) {
let groups = [];
groups.push(0);
el.shaderGroups = groups;
return el;
}

effect.shader:
vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy
#define TAU 6.2831853071795865
float sq(float x)
{
return x*x;
}
vec2 AngRep(vec2 uv, float angle)
{
vec2 polar = vec2(atan(uv.y, uv.x), length(uv));
polar.x = mod(polar.x + angle / 2.0, angle) - angle / 2.0;
return polar.y * vec2(cos(polar.x), sin(polar.x));
}
float sdCircle(vec2 uv, float r)
{
return length(uv) - r;
}
vec3 MixShape(float sd, vec3 fill, vec3 target)
{
float blend = smoothstep(0.0,1.0/acScreenSize.y, sd);
return mix(fill, target, blend);
}
vec2 TunnelPath(float x)
{
vec2 offs = vec2(0, 0);
offs.x = MANUAL? 0.2 * (TAU * x * (1.-EVO.x)) : 0.2 * sin(TAU * x * 0.5) + 0.4 * sin(TAU * x * 0.2 + 0.3);
offs.y = MANUAL? 0.3 * (TAU * x * (1.-EVO.y)) : 0.3 * cos(TAU * x * 0.3) + 0.2 * cos(TAU * x * 0.1);
offs *= smoothstep(1.0,4.0, x);
return offs;
}
void main() {
if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;
vec2 image_size = inputImg.size;
vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
vec2 syamjaidtz;
syamjaidtz = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
syamjaidtz.y*=acLayerSize.y/acLayerSize.x;
syamjaidtz /= scale;
syamjaidtz *= rot2m((0.0+angle)*0.0174533);
syamjaidtz += vec2((-330.0+position.x), (200.0-position.y))*vec2(-1.,1.)/500.;
vec2 scaleVec;
scaleVec = vec2(scale*stretch.x,scale*stretch.y);
syamjaidtz /= scaleVec;
vec4 fragColor;
vec2 res = iResolution.xy / iResolution.y;
vec2 uv = syamjaidtz;
uv -= res/2.0;
vec3 color = vec3(0);
float repAngle = TAU / RING_POINTS;
float pointSize = POINT_SIZE/2.0/iResolution.y;
float camZ;
if(EVOTYPE==0) { camZ = PROGRESS; }
else if(EVOTYPE==1) { camZ = PROGRESS - (acTime*0.5); }
else if(EVOTYPE==2) { camZ = PROGRESS + (acTime*0.5); }
vec2 camOffs = TunnelPath(camZ);
for(int i = 1;i <= int(TUNNEL_LAYERS);i++)
{
float pz = 1.0 - (float(i) / TUNNEL_LAYERS);
pz -= mod(camZ, 4.0 / TUNNEL_LAYERS);
vec2 offs = TunnelPath(camZ + pz) - camOffs;
float ringRad = 0.15 * (1.0 / sq(pz * 0.8 + 0.4));
if(abs(length(uv + offs) - ringRad) < pointSize * 1.5)
{
vec2 aruv = AngRep(uv + offs, repAngle);
float pdist = sdCircle(aruv - vec2(ringRad, 0), pointSize);
vec3 ptColor = (mod(float(i / 2), 2.0) == 0.0) ? vec3(1.0) : vec3(1.0);
float shade = (1.0-pz);
color = MixShape(pdist, ptColor * shade, color);
}
}
fragColor = vec4(color, 1.0);
const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
vec4 gradmap;
float luminance = dot(fragColor.rgb, luminanceWeighting);
gradmap = mix(colorbg,colorfg,luminance)*fragColor.a;
vec4 factor = mix(texColorX,gradmap,1.0);
vec4 resultfinal;
if( blendMode==0 ) {
resultfinal = (factor * hardness) * texColor.a; }
else if( blendMode==1 ) { factor *= hardness;
vec4 c = factor + vec4(1.)*(1.-factor.a);
resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
else if( blendMode==2 ) { factor *= hardness;
resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
gl_FragColor = mix(texColor, resultfinal, alpha);
}
}
